import{_ as t,o,c as s,a2 as a}from"./chunks/framework.BN3Eol-0.js";const f=JSON.parse('{"title":"UXD-030 — The Worlds: a selected orbiter stays visible, is marked, and the view shifts beside its panel","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-030-worlds-selected-orbiter-stays-visible-and-framed.md","filePath":"uxs/decisions/UXD-030-worlds-selected-orbiter-stays-visible-and-framed.md"}'),r={name:"uxs/decisions/UXD-030-worlds-selected-orbiter-stays-visible-and-framed.md"};function i(n,e,d,c,h,l){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="uxd-030-—-the-worlds-a-selected-orbiter-stays-visible-is-marked-and-the-view-shifts-beside-its-panel" tabindex="-1">UXD-030 — The Worlds: a selected orbiter stays visible, is marked, and the view shifts beside its panel <a class="header-anchor" href="#uxd-030-—-the-worlds-a-selected-orbiter-stays-visible-is-marked-and-the-view-shifts-beside-its-panel" aria-label="Permalink to &quot;UXD-030 — The Worlds: a selected orbiter stays visible, is marked, and the view shifts beside its panel&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted (built; the e2e counts are in Verification, a real device is open)</li><li><strong>Date</strong>: 2026-11-14 (proposed and decided)</li><li><strong>Decider</strong>: the operator, 2026-11-14 — the 12 D-series recommendations of the plan (<code>docs/wip/2026-11-11-ux-feedback-plan.md</code> &quot;## D. Worlds&quot;) approved as written; this record covers decisions 1 to 3 of <code>docs/wip/2026-11-13-slice-D1-brief.md</code> §12 (1a, 2a, 3a).</li><li><strong>Answers</strong>: W3 of the UX feedback plan; slice D1</li><li><strong>Builds on</strong>: <a href="./UXD-019-select-equals-focus">UXD-019</a> (select = focus and the panel-aware shift, which item 11 promised the Worlds), <a href="./UXD-024-orbit-ruler-one-row-draws-its-regime">UXD-024</a> (the ruler and its regime highlight, gated by the same orbit rule)</li><li><strong>Changes</strong>: <code>src/lib/surface-scene/surface-view-state.ts</code> (<code>orbitsInViewNext</code>, <code>ORBIT_RULER_HIDE_RADII</code>) and its test, <code>src/lib/three/panel-framing-host.ts</code> (new, with its test: the framing moved out of <code>explore-scene-host.ts</code>), <code>src/lib/three/explore-scene-host.ts</code>, <code>src/lib/surface-scene/SurfaceScene.svelte</code>, <code>src/app.d.ts</code> (<code>__surfaceSceneObjectState</code>), <code>tests/e2e/surface-orbiter-select.spec.ts</code> (new), <code>tests/e2e/footer-dock.spec.ts</code>, <code>tests/e2e/a11y.spec.ts</code>; <a href="./../UXS-005">UXS-005</a>, <a href="./../UXS-006">UXS-006</a>, <a href="./../IA">IA</a>, <code>docs/concept/05_Design_System.md</code>, <code>docs/adr/TA.md</code>, <a href="./../../adr/ADR-072">ADR-072</a>, the module READMEs</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>&quot;Selecting an orbiting object and opening its panel: mark it selected and shift the scene left of the panel so the object shows; now objects are hidden when the panel opens&quot; (W3). Three causes, each checked in a browser:</p><ol><li><strong>The orbit gate hid the selected orbiter.</strong> <code>orbitsInView</code> turns false when the camera is under one body radius above the surface (<code>ORBIT_RULER_HIDE_RADII</code>). The fly-in to an orbiter lands 14 scene units from it, which is 1.1 Mm above the Moon for LRO and 2.3 Mm above Mars for MRO: under one radius on both, so the next frame hid every orbiter dot and ring, the selected one included, and the ruler with them.</li><li><strong>Nothing marked the selected orbiter.</strong> The scene&#39;s own comment said the outline pass marks it; the code outlined only the hovered one, and an orbiter has no halo.</li><li><strong>Nothing shifted the Worlds&#39; view for an open panel.</strong> The shift of UXD-019 existed on <code>/explore</code> only, so on every Worlds route the object the camera had just centred sat under the 400 px panel&#39;s edge.</li></ol><p>A fourth finding came from running it: a deep link (<code>?site=mro</code>) selects as the site list loads, before the frame loop has built the orbital markers, so the fly-in found no marker and was dropped; the camera stayed at the far view.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>Focus on an orbiter means the orbits are in view (decision 1a).</strong> <code>orbitsInViewNext</code> (pure) returns true while an orbiter site or an Earth satellite is selected, so the selected orbiter, its ring, every other orbiter and the ruler stay. Otherwise the old rule stands (hide under one radius, show again above 1.12 radii). The surface-focus behaviour of the gate is unchanged for everything else. The rule and its threshold now live in one place, <code>surface-view-state.ts</code>.</li><li><strong>The selection of an orbiter ends with its panel.</strong> Closing an orbiter&#39;s panel clears the selection (an Earth satellite already did), so the focus rule ends and a low camera hides the orbits again on the next frame. Selecting a site, turning ORBITERS off or closing do the same.</li><li><strong>The view shifts beside the open panel for every selection in the 3D view (decision 2a).</strong> The framing of UXD-019 moved out of the Explore host into <code>createPanelFramer</code> (<code>panel-framing-host.ts</code>), and both hosts call it: the projection shifts by half the docked panel&#39;s width (<code>camera.setViewOffset</code>), measured in the 400 ms after a panel opened, closed or the window resized, eased every frame, instant under reduced motion. A bottom sheet (touch portrait) shifts nothing. On the Worlds it applies in the 3D view and in route view, not in the 2D map, the flat ground patch or a panorama. Picking and every projected overlay read the same camera, so they stay consistent.</li><li><strong>The selected orbiter wears the outline pass, as on hover (decision 3a).</strong> An Earth satellite too. No new asset and no halo.</li><li><strong>The fly-in waits for the marker.</strong> A pending orbiter selection flies as soon as the frame loop has built the markers; the dot is placed on its ring before the fly-in reads its position.</li><li><strong>Test hook.</strong> <code>window.__surfaceSceneObjectState(id)</code> returns <code>{ visible, ringVisible, outlined, x, y }</code> (client px) for an orbiter marker or an Earth satellite, so the e2e checks &quot;drawn&quot;, &quot;outlined&quot; and &quot;centred&quot; without reading pixels.</li></ol><p>No visible text changes: no i18n.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>On <code>/moon</code> (LRO, Lunar Prospector), <code>/mars</code> (MRO) and <code>/earth</code> (ISS) a selected orbiter is drawn with its ring and the outline, the ruler is present beside it, and on a desktop window or a landscape phone the dot sits in the middle of the space the panel leaves.</li><li>The Worlds&#39; bundle grows by the framing helper (a 3.7 kB source file before minification, about 1 kB minified and compressed is the expectation, not measured) and the two functions; <code>explore-scene-host.ts</code> shrinks by the same code, and the helper is one chunk shared by <code>/explore</code> and the Worlds. The route budgets are checked by the operator&#39;s gate at the end of the arc.</li><li>Not done, and named: the shift for a panel docked at the left (RTL) is not handled, here or on <code>/explore</code> (<code>panelCoverPx</code> counts only a panel docked at the right edge); the INDEX drawer is not a <code>Panel</code> and does not shift the view.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p><code>surface-view-state.test.ts</code> (<code>orbitsInViewNext</code>: hides under one radius, stays while an orbiter is the focus, the 12 % band, returns when the focus clears), <code>panel-framing-host.test.ts</code> (a 400 px drawer gives 200 px, the ease, a sheet shifts nothing, the settle window, not wanted takes the shift off), <code>tests/e2e/surface-orbiter-select.spec.ts</code> on <code>desktop-chromium</code>, <code>mobile-chromium</code> and <code>mobile-landscape-chromium</code> (LRO, Lunar Prospector, MRO, ISS drawn, ringed, outlined and centred in the space the panel leaves; the ruler present; closing the panel hides the orbits again at the low camera), <code>footer-dock.spec.ts</code> (no HUD part meets another or the panel with an orbiter selected, <code>/moon</code> and <code>/mars</code>, four sizes), <code>a11y.spec.ts</code> (<code>/moon?site=lro</code>: 0 serious). The spec fails with the rule forced off (mutation check). Screenshots with the panel open were read for LRO and MRO at 1440 x 900, Lunar Prospector at 844 x 390 and LRO at 390 x 844 (the Worlds are drawn with headless WebGL); the hook&#39;s state for LRO, Lunar Prospector and MRO at all three sizes was read as numbers (dot at the middle of the space the panel leaves on desktop and landscape, at the screen centre on the portrait phone). Not checked: <code>ar</code> (RTL), a real device.</p>',13)])])}const p=t(r,[["render",i]]);export{f as __pageData,p as default};
